// ─── File: ActiveAccountDemo.java ───
// Compares INNER JOIN + DISTINCT vs EXISTS semi-join (rows inspected).
package com.bank.active;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ActiveAccountDemo {
    private static final Logger log = Logger.getLogger(ActiveAccountDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BankRepository repo = new BankRepository();
        ActiveAccountService service = new ActiveAccountService(repo);

        log.info("=== INNER JOIN + DISTINCT (slow: duplicates then de-dups) ===");
        ActiveAccountService.Result join = service.activeViaJoinDistinct();
        join.accounts.forEach(id -> log.info("active: " + id));
        log.warning(() -> "intermediate rows before DISTINCT = " + join.rowsInspected);

        log.info("=== EXISTS semi-join (fast: once each, short-circuit) ===");
        ActiveAccountService.Result exists = service.activeViaExists();
        exists.accounts.forEach(id -> log.info("active: " + id));
        log.info(() -> "child rows inspected (short-circuit) = " + exists.rowsInspected);
    }
}

// ─── Would be in model/Account.java ───
class Account {
    final String accountId, holderName;
    Account(String id, String name) { this.accountId = id; this.holderName = name; }
}

// ─── Would be in model/Txn.java ───
class Txn {
    final String txnId, accountId; final BigDecimal amount;
    Txn(String id, String acct, BigDecimal amt) {
        this.txnId = id; this.accountId = acct; this.amount = amt;
    }
}

// ─── Would be in repository/BankRepository.java ───
class BankRepository {
    List<Account> accounts() {
        return List.of(new Account("SAV2001", "Rajesh Kumar"),
                       new Account("CUR3001", "Priya Sharma"),
                       new Account("SAV2002", "Amit Verma"));
    }
    List<Txn> txns() {
        return List.of(
            new Txn("TX1", "SAV2001", new BigDecimal("40000")),
            new Txn("TX2", "SAV2001", new BigDecimal("10000")),
            new Txn("TX3", "SAV2001", new BigDecimal("5000")),
            new Txn("TX4", "SAV2001", new BigDecimal("2000")),
            new Txn("TX5", "CUR3001", new BigDecimal("25000")));
    }
}

// ─── Would be in service/ActiveAccountService.java ───
class ActiveAccountService {
    private final BankRepository repo;
    ActiveAccountService(BankRepository repo) { this.repo = repo; }

    static class Result {
        final List<String> accounts; final int rowsInspected;
        Result(List<String> a, int r) { this.accounts = a; this.rowsInspected = r; }
    }

    // INNER JOIN + DISTINCT: form every matching pair, then de-duplicate.
    Result activeViaJoinDistinct() {
        List<String> pairs = new ArrayList<>();
        int inspected = 0;
        for (Account a : repo.accounts()) {
            for (Txn t : repo.txns()) {           // scans ALL txns per account
                inspected++;
                if (a.accountId.equals(t.accountId)) pairs.add(a.accountId); // duplicate row
            }
        }
        // DISTINCT step: collapse duplicates (extra work)
        List<String> distinct = new ArrayList<>(new LinkedHashSet<>(pairs));
        return new Result(distinct, inspected);
    }

    // EXISTS semi-join: stop at the first matching txn per account.
    Result activeViaExists() {
        List<String> result = new ArrayList<>();
        int inspected = 0;
        for (Account a : repo.accounts()) {
            boolean found = false;
            for (Txn t : repo.txns()) {
                inspected++;
                if (a.accountId.equals(t.accountId)) { found = true; break; } // short-circuit
            }
            if (found) result.add(a.accountId);   // added exactly once
        }
        return new Result(result, inspected);
    }
}

